func fit(v []Triple)(float64,float64,bool){n:=float64(len(v));t,x:=0.,0.;for _,a:=range v {t+=a[0];x+=a[1]-a[2]};if t<=0||n<2{return 0,0,false};d:=x/t;s:=0.;for _,a:=range v {e:=a[1]-a[2]-d*a[0];s+=e};center:=s/n;squares:=0.;for _,a:=range v {e:=a[1]-a[2]-d*a[0];z:=e-center;squares+=z*z};variance:=n*squares/((n-1)*(t*t));return d,variance,true}
